from jsonb_to_recordset($json$[{"id":"che-st-161","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Thermal decomposition $\\mathrm{CaCO_3} \\rightarrow \\mathrm{CaO} + \\mathrm{CO_2}$ is 1 : 1 : 1 in moles. From 1 mol of limestone the carbon dioxide obtained is","options":["0.5 mol","1 mol","2 mol","3 mol"],"answer_index":1,"explanation":"Each mole of $\\mathrm{CaCO_3}$ yields one mole of $\\mathrm{CO_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-162","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The laboratory oxygen preparation $2\\mathrm{KClO_3} \\rightarrow 2\\mathrm{KCl} + 3\\mathrm{O_2}$ gives, from 2 mol of chlorate, oxygen amounting to","options":["2 mol","3 mol","4 mol","6 mol"],"answer_index":1,"explanation":"The O$_2$ coefficient is 3 when 2 mol of $\\mathrm{KClO_3}$ decompose.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-163","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Complete combustion $\\mathrm{C} + \\mathrm{O_2} \\rightarrow \\mathrm{CO_2}$ links carbon and carbon dioxide in the mole ratio","options":["1 : 1","1 : 2","2 : 1","1 : 4"],"answer_index":0,"explanation":"Coefficients of C and $\\mathrm{CO_2}$ are both 1.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-164","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Magnesium burns as $2\\mathrm{Mg} + \\mathrm{O_2} \\rightarrow 2\\mathrm{MgO}$. Oxygen amounting to 1 mol therefore requires magnesium equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"Two moles of Mg are needed for each mole of $\\mathrm{O_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-165","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Methane burns as $\\mathrm{CH_4} + 2\\mathrm{O_2} \\rightarrow \\mathrm{CO_2} + 2\\mathrm{H_2O}$. The oxygen-to-methane mole ratio demanded by the equation is","options":["1 : 1","2 : 1","1 : 2","4 : 1"],"answer_index":1,"explanation":"Two moles of $\\mathrm{O_2}$ are required for every mole of $\\mathrm{CH_4}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-166","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Contact-process oxidation $2\\mathrm{SO_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{SO_3}$ converts 1 mol of oxygen into sulphur trioxide amounting to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"One mole of $\\mathrm{O_2}$ produces two moles of $\\mathrm{SO_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-167","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Aluminium burns in oxygen: $4\\mathrm{Al} + 3\\mathrm{O_2} \\rightarrow 2\\mathrm{Al_2O_3}$. Four moles of aluminium therefore form alumina equal to","options":["1 mol","2 mol","3 mol","4 mol"],"answer_index":1,"explanation":"The product coefficient is 2 when 4 mol of Al react.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-168","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Hydrogen chloride is formed by $\\mathrm{H_2} + \\mathrm{Cl_2} \\rightarrow 2\\mathrm{HCl}$. One mole of hydrogen gas yields HCl equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"The HCl coefficient is 2 for each mole of $\\mathrm{H_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-169","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Propane burns as $\\mathrm{C_3H_8} + 5\\mathrm{O_2} \\rightarrow 3\\mathrm{CO_2} + 4\\mathrm{H_2O}$. Complete combustion of 2 mol of propane releases carbon dioxide amounting to","options":["2 mol","3 mol","6 mol","8 mol"],"answer_index":2,"explanation":"Each mole of $\\mathrm{C_3H_8}$ gives 3 mol $\\mathrm{CO_2}$, so 2 mol give 6 mol.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-170","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A Haber converter is charged with 10 mol of hydrogen and surplus nitrogen. The maximum ammonia that can form is","options":["6.67 mol","10 mol","15 mol","20 mol"],"answer_index":0,"explanation":"From $3\\mathrm{H_2} \\rightarrow 2\\mathrm{NH_3}$, 10 mol H$_2$ produce $(10 \\times 2)/3 = 20/3 \\approx 6.67$ mol NH$_3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
